export const ACNABIN_LOGO_BASE64 = '';

export function getAcnabinLogoBuffer(): Uint8Array {
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(ACNABIN_LOGO_BASE64, 'base64');
  }
  const binary = atob(ACNABIN_LOGO_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
